<script setup lang="ts">
import { ref } from 'vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { Settings, Plus, Users, Wallet, CircleMinus, Banknote, Search } from '@lucide/vue';
import AppLayout from '@/Layouts/AppLayout.vue';
const page = usePage<any>();
const props = defineProps<{ period: string; run: any; items: any; totals: any; search: string; availablePeriods: string[] }>();
const month = ref(props.period); const search = ref(props.search); const showCreate = ref(false); const expanded = ref<number | null>(null);
const form = useForm({ period: props.period, payment_date: '' });
const money = (n: number | string) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(n || 0));
const statuses: Record<string, string> = { DRAFT: 'Draf', REVIEWED: 'Ditinjau', APPROVED: 'Disetujui', PAID: 'Dibayar' };
const next: Record<string, {status:string; label:string}> = { DRAFT:{status:'REVIEWED',label:'Tandai Ditinjau'}, REVIEWED:{status:'APPROVED',label:'Setujui Payroll'}, APPROVED:{status:'PAID',label:'Tandai Dibayar'} };
const filter = () => router.get('/dashboard/payroll', { period: month.value, search: search.value }, { preserveState: true, replace: true });
const create = () => form.post('/dashboard/payroll', { onSuccess: () => { showCreate.value = false; } });
const advance = () => { const action = next[props.run?.status]; if (action && confirm(action.status === 'PAID' ? 'Pastikan pembayaran sudah dilakukan. Tombol ini hanya mencatat status, bukan melakukan transfer. Lanjutkan?' : `Lanjutkan: ${action.label}?`)) router.patch(`/dashboard/payroll/${props.run.id}/status`, { status: action.status }); };
const deleteDraft = () => { if (confirm('Hapus draf payroll ini? Draf dapat dibuat ulang dengan data terbaru.')) router.delete(`/dashboard/payroll/${props.run.id}`); };
const details = (value: any) => { try { return typeof value === 'string' ? JSON.parse(value) : value || []; } catch { return []; } };
</script>
<template>
<Head title="Payroll Pegawai" /><AppLayout><main class="payroll mx-auto max-w-[1600px] space-y-5 p-3 sm:p-5">
<div class="flex flex-wrap items-center justify-between gap-4"><div><p class="muted text-sm">Dashboard / Payroll</p><h1 class="mt-1 text-2xl font-black">Payroll Pegawai</h1><p class="muted mt-1 text-sm">Kelola dan pantau penggajian pegawai berdasarkan periode.</p></div><div class="flex gap-2"><Link href="/dashboard/payroll/salaries" class="secondary"><Users class="h-4 w-4" /> Data Gaji Karyawan</Link><Link href="/dashboard/payroll/settings" class="secondary"><Settings class="h-4 w-4" /> Pengaturan Payroll</Link><button class="primary" @click="showCreate = true"><Plus class="h-4 w-4" /> Buat Payroll</button></div></div>
<div v-if="page.props.flash?.success" class="notice">{{ page.props.flash.success }}</div>
<div v-if="Object.keys(page.props.errors || {}).length" class="error">{{ Object.values(page.props.errors || {}).join(' ') }}</div>
<div class="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><div v-for="card in [{label:'Total Pegawai',value:totals.employees,icon:Users},{label:'Total Gaji Kotor',value:money(totals.gross),icon:Wallet},{label:'Total Potongan',value:money(totals.deductions),icon:CircleMinus},{label:'Total Gaji Bersih',value:money(totals.net),icon:Banknote}]" :key="card.label" class="panel flex items-center gap-4"><span class="icon"><component :is="card.icon" class="h-6 w-6" /></span><div><p class="muted text-sm">{{ card.label }}</p><p class="mt-1 text-xl font-black">{{ card.value }}</p></div></div></div>
<section class="panel flex flex-wrap items-end justify-between gap-4"><div class="flex flex-wrap items-end gap-5"><label>Periode Penggajian<input v-model="month" type="month" @change="filter" /></label><div><p class="muted text-xs">Status</p><span class="badge">{{ run ? statuses[run.status] : 'Belum dibuat' }}</span></div><div><p class="muted text-xs">Tanggal pembayaran</p><strong>{{ run?.payment_date || '—' }}</strong></div></div><div class="flex gap-2"><button v-if="run?.status === 'DRAFT'" class="secondary" @click="deleteDraft">Hapus Draf</button><button v-if="run && next[run.status]" class="primary" @click="advance">{{ next[run.status].label }}</button></div></section>
<section class="panel"><div class="flex flex-wrap items-center justify-between gap-3"><h2>Daftar Penggajian Pegawai</h2><form class="flex gap-2" @submit.prevent="filter"><input v-model="search" placeholder="Cari nama pegawai" aria-label="Cari nama pegawai" /><button class="secondary"><Search class="h-4 w-4" /> Cari</button></form></div>
<div class="mt-4 overflow-x-auto"><table><thead><tr><th>Pegawai</th><th>Gaji Pokok</th><th>Tunjangan</th><th>Total Potongan</th><th>Gaji Bersih</th><th>Rincian</th></tr></thead><tbody><template v-for="item in items.data" :key="item.id"><tr><td class="font-bold">{{ item.employee_name }}</td><td>{{ money(item.base_salary) }}</td><td>{{ money(item.allowance) }}</td><td>{{ money(Number(item.late_deduction) + Number(item.other_deduction)) }}</td><td class="font-bold">{{ money(item.net_salary) }}</td><td><button class="secondary" @click="expanded = expanded === item.id ? null : item.id">{{ expanded === item.id ? 'Tutup' : 'Detail' }}</button></td></tr><tr v-if="expanded === item.id"><td colspan="6"><p class="font-bold">Rincian komponen gaji</p><div v-if="item.salary_details" class="mt-2"><p>Tunjangan tetap: {{ money(details(item.salary_details).fixed_allowance) }}</p><p v-for="(a, i) in details(item.salary_details).other_allowances" :key="i">{{ a.name }}: {{ money(a.amount) }}</p><p>BPJS Kesehatan: {{ money(details(item.salary_details).bpjs_health) }}</p><p>BPJS Ketenagakerjaan: {{ money(details(item.salary_details).bpjs_employment) }}</p></div><p class="font-bold mt-3">Rincian keterlambatan</p><ul v-if="details(item.late_details).length" class="mt-2 space-y-1"><li v-for="(entry,i) in details(item.late_details)" :key="i">{{ entry.date }} · absen {{ entry.check_in }} · {{ entry.minutes }} menit · {{ money(entry.amount) }}</li></ul><p v-else class="muted mt-2">Tidak ada potongan keterlambatan yang tercatat.</p></td></tr></template><tr v-if="!items.data.length"><td colspan="6" class="muted py-6 text-center">{{ run ? 'Tidak ada pegawai yang cocok dengan pencarian.' : 'Belum ada payroll pada periode ini. Atur gaji pegawai lalu buat payroll.' }}</td></tr></tbody></table></div>
<div class="mt-4 flex flex-wrap items-center justify-between gap-3 text-sm muted"><span>Menampilkan {{ items.from || 0 }}–{{ items.to || 0 }} dari {{ items.total }} pegawai</span><div class="flex gap-2"><Link v-if="items.prev_page_url" :href="items.prev_page_url" class="secondary">Sebelumnya</Link><Link v-if="items.next_page_url" :href="items.next_page_url" class="secondary">Berikutnya</Link></div></div></section>
<section class="panel"><h2>Alur Payroll</h2><p class="muted mt-2 text-sm">Draf → Ditinjau → Disetujui → Dibayar. Status dibayar adalah pencatatan manual; sistem tidak melakukan transfer bank. BPJS menggunakan nominal yang diatur per pegawai; pajak belum dihitung otomatis.</p></section>
<div v-if="showCreate" class="overlay" @click.self="showCreate = false"><form class="modal" @submit.prevent="create"><div class="flex justify-between gap-4"><h2>Buat Payroll</h2><button type="button" aria-label="Tutup" @click="showCreate = false">✕</button></div><p class="muted mt-2 text-sm">Payroll menggunakan gaji dan absensi yang tersimpan saat draf dibuat.</p><label class="mt-4 block">Periode<input v-model="form.period" type="month" required /></label><label class="mt-3 block">Tanggal pembayaran (opsional)<input v-model="form.payment_date" type="date" /></label><p v-if="form.errors.period" class="error mt-3">{{ form.errors.period }}</p><p v-if="form.errors.payment_date" class="error mt-3">{{ form.errors.payment_date }}</p><div class="mt-5 flex justify-end gap-2"><button type="button" class="secondary" @click="showCreate = false">Batal</button><button class="primary" :disabled="form.processing">Buat Draf</button></div></form></div>
</main></AppLayout>
</template>
<style scoped>
.payroll{color:#261a11}.panel{background:#fff;border:1px solid #e8dfcf;border-radius:16px;padding:20px}.panel h2,.modal h2{font-size:1.05rem;font-weight:800}.muted{color:#70685e}.icon{display:grid;place-items:center;width:48px;height:48px;border-radius:12px;background:#fbefd0;color:#9a6a00}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;border-radius:10px;padding:10px 14px;font-weight:700;font-size:.85rem;white-space:nowrap}.primary{background:#d4af37;color:#1b1505}.secondary{border:1px solid #c49b24;color:#785600;background:#fff}.primary:disabled{opacity:.6}.badge{display:inline-block;margin-top:4px;border-radius:999px;background:#fff0c8;color:#775200;padding:5px 12px;font-size:.75rem;font-weight:700}.payroll input{display:block;border:1px solid #d8cdbd;border-radius:10px;background:#fff;color:#261a11;padding:10px}.payroll label{font-size:.85rem;font-weight:600}.payroll label input{width:100%;margin-top:5px}table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap;font-size:.85rem}th,td{padding:12px;border-bottom:1px solid #eee5d6}th{background:#f7f1e7}td[colspan]{white-space:normal}.notice,.error{padding:12px;border-radius:10px;background:#faf3e3}.error{background:#ffeded;color:#9b1c1c}.overlay{position:fixed;inset:0;z-index:100;display:grid;place-items:center;background:#0009;padding:20px}.modal{width:min(100%,480px);background:white;border-radius:18px;padding:24px;color:#261a11}
</style>
